    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]

        N = len(grid)
        box_size = int(math.sqrt(N))

        def is_valid_move(board, row, col, num):
            # Check row
            if num in board[row]:
                return False

            # Check column
            for r in range(N):
                if board[r][col] == num:
                    return False

            # Check subgrid
            start_row = row - row % box_size
            start_col = col - col % box_size
            for r in range(box_size):
                for c in range(box_size):
                    if board[start_row + r][start_col + c] == num:
                        return False

            return True

        def get_valid_moves(board, prev_move):
            valid_moves = []

            if prev_move is None:
                # First move can be anywhere
                for row in range(N):
                    for col in range(N):
                        if board[row][col] == 0:
                            for num in range(1, N+1):
                                if is_valid_move(board, row, col, num):
                                    valid_moves.append(((row, col), num))
            else:
                # Subsequent moves must be in same row or column as last move
                last_row, last_col = prev_move[0]

                # Check same row
                for col in range(N):
                    if board[last_row][col] == 0:
                        for num in range(1, N+1):
                            if is_valid_move(board, last_row, col, num):
                                valid_moves.append(((last_row, col), num))

                # Check same column
                for row in range(N):
                    if board[row][last_col] == 0:
                        for num in range(1, N+1):
                            if is_valid_move(board, row, last_col, num):
                                valid_moves.append(((row, last_col), num))

                # If no valid moves in same row/column, can move anywhere
                if not valid_moves:
                    for row in range(N):
                        for col in range(N):
                            if board[row][col] == 0:
                                for num in range(1, N+1):
                                    if is_valid_move(board, row, col, num):
                                        valid_moves.append(((row, col), num))

            return valid_moves

        def is_winning_move(board, move):
            # Make a copy of the board
            new_board = copy.deepcopy(board)
            row, col = move[0]
            num = move[1]
            new_board[row][col] = num

            # Get opponent's possible moves after this move
            opponent_moves = get_valid_moves(new_board, move)

            # If opponent has no valid moves, this is a winning move
            return len(opponent_moves) == 0

        # Get all valid moves
        valid_moves = get_valid_moves(grid, prev_move)

        # First check for immediate winning moves
        for move in valid_moves:
            if is_winning_move(grid, move):
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=move, type='custom')]
                )

        # If no immediate win, choose move that minimizes opponent's options
        if valid_moves:
            # Sort moves by how many options they leave the opponent
            move_scores = []
            for move in valid_moves:
                new_board = copy.deepcopy(grid)
                row, col = move[0]
                num = move[1]
                new_board[row][col] = num
                opponent_moves = get_valid_moves(new_board, move)
                move_scores.append((move, len(opponent_moves)))

            # Choose move with minimum opponent options
            best_move = min(move_scores, key=lambda x: x[1])[0]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=best_move, type='custom')]
            )

        # Shouldn't reach here if game isn't already over
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=None, type='custom')]
        )

