    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def get_subgrid(self, grid, row, col):
        n = len(grid)
        size = int(n ** 0.5)
        start_row = (row // size) * size
        start_col = (col // size) * size
        return [grid[i][j] for i in range(start_row, start_row + size) 
                          for j in range(start_col, start_col + size)]

    def is_valid_move(self, grid, row, col, num):
        # Check row
        if num in grid[row]:
            return False

        # Check column
        if num in [grid[i][col] for i in range(len(grid))]:
            return False

        # Check subgrid
        if num in self.get_subgrid(grid, row, col):
            return False

        return True

    def get_valid_moves(self, grid, prev_move):
        n = len(grid)
        valid_moves = []

        if prev_move is None:
            # First move can be anywhere
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        for num in range(1, n + 1):
                            if self.is_valid_move(grid, i, j, num):
                                valid_moves.append(((i, j), num))
        else:
            # Subsequent moves must be in same row or column
            prev_row, prev_col = prev_move[0]

            # Check same row
            for j in range(n):
                if grid[prev_row][j] == 0:
                    for num in range(1, n + 1):
                        if self.is_valid_move(grid, prev_row, j, num):
                            valid_moves.append(((prev_row, j), num))

            # Check same column
