            if not valid_moves:
                for i in range(n):
                    for j in range(n):
                        if grid[i][j] == 0:
                            for num in range(1, n + 1):
                                if self.is_valid_move(grid, i, j, num):
                                    valid_moves.append(((i, j), num))

        return valid_moves

    def find_winning_move(self, grid, prev_move):
        valid_moves = self.get_valid_moves(grid, prev_move)

        for move in valid_moves:
            (row, col), num = move

            # Make a copy of the grid and apply the move
            new_grid = [row.copy() for row in grid]
            new_grid[row][col] = num

            # Check if opponent has any valid moves after this
            opponent_moves = self.get_valid_moves(new_grid, move)

            if not opponent_moves:
                return move

        return None

