        winning_move = self.find_winning_move(grid, prev_move)
        if winning_move is not None:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=winning_move, type='custom')]
            )

        # If no immediate winning move, pick the move that leaves opponent with fewest options
        valid_moves = self.get_valid_moves(grid, prev_move)
        if not valid_moves:
            # No valid moves (shouldn't happen unless board is full)
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

        # Find move that minimizes opponent's options
        best_move = None
        min_opponent_moves = float('inf')

        for move in valid_moves:
            (row, col), num = move
            new_grid = [row.copy() for row in grid]
