            new_grid = copy.deepcopy(grid)
            new_grid[row][col] = num
            opponent_moves = self.get_valid_moves(new_grid, move)
            score += (N*N - len(opponent_moves)) * 50

            move_scores.append(score)

        # Return move with highest score
        return valid_moves[move_scores.index(max(move_scores))]

