                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=winning_move, type='custom')]
            )

        # If no immediate win, choose the best strategic move
        best_move = self.get_best_strategic_move(grid, valid_moves)

        return Info(
