                    if grid[i][j] == 0:
                        for num in range(1, n+1):
                            if self.is_valid_move(grid, i, j, num, n):
                                valid_moves.append([(i, j), num])
        else:
            # Subsequent moves must be in same row or column as last move
            last_row, last_col = prev_move[0][0], prev_move[0][1]

            # Check same row
