                        if self.is_valid_move(grid, last_row, col, num, n):
                            valid_moves.append([(last_row, col), num])

            # Check same column
            for row in range(n):
                if grid[row][last_col] == 0 and row != last_row:
                    for num in range(1, n+1):
                        if self.is_valid_move(grid, row, last_col, num, n):
                            valid_moves.append([(row, last_col), num])

            # If no valid moves in same row/column, can move anywhere
            if not valid_moves:
